import Base

type Tree is Data:
  Leaf{key: String}
  Branch{children: List<&2, Tree>}

def map_children(~f: Tree -> String -> Tree, children: List<&2, Tree>, +prefix: String) -> List<&2, Tree>:
  match children:
    case Nil{}: Nil{}
    case child <> rest:
      f(child, prefix) <> map_children(~f, rest, prefix)

@unsafe
def rename(tree: Tree, +prefix: String) -> Tree:
  match tree:
    case Leaf{key}: Leaf{String.append(prefix, key)}
    case Branch{children}: Branch{map_children(~(tree => prefix => rename(tree, prefix)), children, prefix)}

def input() -> Tree:
  Branch{[Leaf{"left"}, Leaf{"right"}]}

def result(ok: Bool) -> String:
  match ok:
    case True{}: "template-env-ok"
    case False{}: "template-env-failed"

def verify(tree: Tree, +prefix: String) -> String:
  match tree:
    case Branch{Leaf{left} <> Leaf{right} <> Nil{}}:
      result(Bool.and(String.eq(left, String.append(prefix, "left")), String.eq(right, String.append(prefix, "right"))))
    case _: "template-env-failed"

def run(seed: U32) -> String:
  +prefix = U32.show(seed)
  verify(rename(input(), prefix), prefix)

def main() -> IO(Unit):
  do IO<Unit>:
    seed : U32 <- IO.thread_count()
    IO.print(run(seed))

#|template-env-ok
